iches, sale et sers avec du riz.","timer":null}]},{"title":"Gaspacho","intro":"La soupe froide andalouse : tomates, concombre et poivron, mixés avec un filet d'huile d'olive.","minutes":15,"calories":140,"difficulty":"Facile","imageSearch":"gazpacho cold tomato soup","veg":true,"oven":false,"cold":true,"missing":"","origin":"Plat espagnol","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":6,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"vinaigre de xérès","plural":"vinaigre de xérès","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les légumes en morceaux.","timer":null},{"text":"Mixe-les avec l'ail, l'huile, le vinaigre, sel et poivre, jusqu'à ce que ce soit bien lisse.","timer":null},{"text":"Mets au frais au moins 2 h avant de servir.","timer":{"label":"Frais","min":120}}]},{"title":"Velouté de courgettes","intro":"Un velouté vert et onctueux, adouci avec un peu de fromage fondu.","minutes":30,"calories":150,"difficulty":"Facile","imageSearch":"zucchini soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"fromage fondu","plural":"fromages fondus","qty":4,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have